UPDATE openbiz_work_order
SET assignee_user_id = #{assigneeUserId},
    status = #{toStatus},
    update_time = NOW()
WHERE id = #{id}
  AND tenant_id = #{tenantId}
  AND status = #{fromStatus}

UPDATE openbiz_work_order
SET status = #{toStatus},
    complete_note = #{completeNote},
    update_time = NOW()
WHERE id = #{id}
  AND tenant_id = #{tenantId}
  AND status = #{fromStatus}
